#pragma weak allocator_get_stats
#pragma weak allocator_validate
#pragma weak allocator_strategy_name

enum { SLOTS = 1024 };
enum workload { UNIFORM, MIXED, FRAGMENTED, RESIZE };
enum allocation { USE_MALLOC, USE_CALLOC, USE_REALLOC };

struct slot {
    unsigned char *ptr;
    size_t size;
    unsigned char pattern;
};

struct operations {
    size_t malloc_calls, calloc_calls, realloc_calls, free_calls;
};

struct allocator_info {
    const char *library, *variant, *strategy;
    bool instrumented; // whther library has stats functions
};

struct checkpoint {
    uint64_t rss_kib, peak_rss_kib;
    struct allocator_stats stats;
};

static struct slot slots[SLOTS];
static struct operations calls;
static size_t live_requested, peak_live_requested;
static uint64_t checksum;

static void fail(const char *message) {
    fprintf(stderr, "benchmark: %s\n", message);
    exit(EXIT_FAILURE);
}

static void usage(FILE *stream, const char *program) {
    fprintf(stream,
            "Usage: %s uniform|mixed|fragmented|resize SEED STEPS [system|first|best|next] "
            "[--size-scale N]\n"
            "SEED must be 1..4294967295; STEPS must be positive.\n"
            "Size scale is a positive integer multiplier (default 1).\n"
            "Writes one JSON result. The optional label checks the loaded allocator.\n",
            program);
}

static uintmax_t parse_number(const char *text, uintmax_t maximum) {
    if (text[0] < '0' || text[0] > '9')
        fail("numeric arguments must be positive decimal integers");
    char *end;
    errno = 0;
    uintmax_t value = strtoumax(text, &end, 10);
    if (errno == ERANGE || *end || !value || value > maximum)
        fail("numeric argument is invalid or out of range");
    return value;
}

static bool valid_label(const char *label) {
    return strcmp(label, "system") == 0 || strcmp(label, "first") == 0 ||
           strcmp(label, "best") == 0 || strcmp(label, "next") == 0;
}

/* Resolve symbols before timing, including the plain allocator without diagnostics.
   dlsym avoids mistaking the executable's PLT entry for the actual provider. */
static const char *symbol_library(const char *name) {
    dlerror();
    void *address = dlsym(RTLD_DEFAULT, name);
    const char *error = dlerror();
    Dl_info info;
    if (error || !address || !dladdr(address, &info) || !info.dli_fname)
        fail("cannot identify the library supplying the allocation functions");
    return info.dli_fname;
}

static struct allocator_info identify_allocator(const char *expected) {
    struct allocator_info info = {.library = symbol_library("malloc")};
    const char *functions[] = {"free", "calloc", "realloc"};

    for (size_t i = 0; i < sizeof(functions) / sizeof(functions[0]); ++i) {
        if (strcmp(info.library, symbol_library(functions[i])) != 0)
            fail("allocation functions resolve to different libraries");
    }

    const char *base = strrchr(info.library, '/');
    base = base ? base + 1 : info.library;
    if (strcmp(base, "libc.so.6") == 0) {
        info.variant = "glibc";
        info.strategy = "system";
    } else if (strcmp(base, "liballocator.so") == 0 ||
               strcmp(base, "liballocator_with_stats.so") == 0) {
        info.instrumented = strcmp(base, "liballocator_with_stats.so") == 0;
        info.variant = info.instrumented ? "stats" : "plain";
        const char *name = getenv("ALLOC_STRATEGY");
        info.strategy = name && strcmp(name, "best") == 0   ? "best"
                        : name && strcmp(name, "next") == 0 ? "next"
                                                            : "first";
    } else {
        fail("unrecognized allocator library; use glibc or the libraries built by make");
    }

    bool any_diagnostics = allocator_get_stats || allocator_validate || allocator_strategy_name;
    if (info.instrumented) {
        if (!(allocator_get_stats && allocator_validate && allocator_strategy_name))
            fail("instrumented allocator diagnostics are missing");
        if (strcmp(info.strategy, allocator_strategy_name()) != 0)
            fail("allocator strategy disagrees with ALLOC_STRATEGY");
    } else if (any_diagnostics) {
        fail("diagnostics belong to a different allocator; preload only one allocator library");
    }
    if (expected && strcmp(expected, info.strategy) != 0)
        fail("loaded allocator does not match the expected label");
    return info;
}

static uint64_t now_ns(void) {
    struct timespec time;
    if (clock_gettime(CLOCK_MONOTONIC, &time) != 0)
        fail("clock_gettime failed");
    return (uint64_t)time.tv_sec * UINT64_C(1000000000) + (uint64_t)time.tv_nsec;
}

/* Fixed buffers and open/read keep measurement bookkeeping off the allocator's heap. */
static uint64_t proc_kib(const char *path, const char *field) {
    char buffer[8192];
    int fd = open(path, O_RDONLY | O_CLOEXEC);
    if (fd < 0)
        fail("cannot open Linux procfs memory information");
    size_t used = 0;
    while (used < sizeof(buffer) - 1) {
        ssize_t count = read(fd, buffer + used, sizeof(buffer) - 1 - used);
        if (count < 0) {
            if (errno == EINTR)
                continue;
            close(fd);
            fail("cannot read Linux procfs memory information");
        }
        if (!count)
            break;
        used += (size_t)count;
    }
    close(fd);
    buffer[used] = '\0';

    size_t field_length = strlen(field);
    for (const char *line = buffer; line && *line;) {
        if (strncmp(line, field, field_length) == 0) {
            const char *p = line + field_length;
            while (*p == ' ' || *p == '\t')
                ++p;
            if (*p < '0' || *p > '9')
                fail("invalid procfs memory field");
            uint64_t value = 0;
            while (*p >= '0' && *p <= '9') {
                unsigned digit = (unsigned)(*p++ - '0');
                if (value > (UINT64_MAX - digit) / 10)
                    fail("procfs memory value overflow");
                value = value * 10 + digit;
            }
            while (*p == ' ' || *p == '\t')
                ++p;
            if (strncmp(p, "kB", 2) != 0)
                fail("unexpected procfs memory unit");
            return value;
        }
        line = strchr(line, '\n');
        if (line)
            ++line;
    }
    fail("required procfs memory field is missing; Linux smaps_rollup is required");
    return 0;
}

static void capture_checkpoint(struct checkpoint *out, bool instrumented) {
    if (instrumented) {
        if (!allocator_validate() || allocator_get_stats(&out->stats) != 0)
            fail("allocator validation or statistics snapshot failed");
    }
    out->rss_kib = proc_kib("/proc/self/smaps_rollup", "Rss:");
    /* VmHWM is an approximate process-lifetime peak, not an exact sampled RSS. */
    out->peak_rss_kib = proc_kib("/proc/self/status", "VmHWM:");
}

static uint32_t random_number(uint32_t *state) {
    *state ^= *state << 13;
    *state ^= *state >> 17;
    *state ^= *state << 5;
    return *state;
}

/* Correctness tests check full buffers; this benchmark samples their boundaries and middle. */
static void verify_samples(const unsigned char *ptr, size_t size, unsigned char pattern) {
    if (!size)
        return;
    if (ptr[0] != pattern || ptr[size / 2] != pattern || ptr[size - 1] != pattern)
        fail("allocation contents or realloc preservation corrupted");
    checksum = checksum * UINT64_C(1099511628211) + ptr[0] + ptr[size / 2] + ptr[size - 1] + size;
}

static void discard(size_t index) {
    struct slot *slot = &slots[index];
    verify_samples(slot->ptr, slot->size, slot->pattern);
    free(slot->ptr);
    ++calls.free_calls;
    live_requested -= slot->size;
    *slot = (struct slot){0};
}

static void assign(size_t index, size_t size, unsigned char pattern, enum allocation kind) {
    struct slot *slot = &slots[index];
    if (slot->ptr)
        verify_samples(slot->ptr, slot->size, slot->pattern);

    unsigned char *ptr;
    if (kind == USE_REALLOC) {
        ptr = realloc(slot->ptr, size);
        ++calls.realloc_calls;
    } else if (kind == USE_CALLOC) {
        ptr = calloc(1, size);
        ++calls.calloc_calls;
    } else {
        ptr = malloc(size);
        ++calls.malloc_calls;
    }
    if (!ptr)
        fail("allocation failed; this run must not be used as a benchmark result");
    if ((uintptr_t)ptr % _Alignof(max_align_t))
        fail("allocation is not suitably aligned");

    if (kind == USE_REALLOC) {
        size_t preserved = size < slot->size ? size : slot->size;
        verify_samples(ptr, preserved, slot->pattern);
    } else if (kind == USE_CALLOC) {
        verify_samples(ptr, size, 0);
    }

    live_requested = live_requested - slot->size + size;
    if (live_requested > peak_live_requested)
        peak_live_requested = live_requested;
    slot->ptr = ptr;
    slot->size = size;
    slot->pattern = pattern;
    /* Fault in and write every requested byte for meaningful resident-memory measurements. */
    memset(ptr, pattern, size);
}

/**
 * Exercise allocation, reuse, and resizing with a deterministic request sequence.
 * The 1,024 global slots initially contain no allocations. Each occupied slot
 * records its pointer, requested size, and expected payload byte pattern.
 *
 * FRAGMENTED setup (the other workloads have no setup):
 * - Allocate every slot with malloc, requesting 64 + (index % 8) * 128 bytes.
 *   Sizes therefore repeat 64, 192, 320, 448, 576, 704, 832, and 960 bytes.
 * - Free the 512 even-indexed slots. The odd-indexed allocations stay alive
 *   throughout the loop, mixing long-lived objects with reusable holes.
 *   Their actual physical placement is determined by the allocator.
 * - These 1,024 malloc calls and 512 free calls are included in the timed setup.
 *
 * Each main-loop iteration draws three PRNG values: a slot index in 0..1,023,
 * an operation choice, and size_bits. FRAGMENTED clears the index's low bit
 * so only even slots are selected and its odd-slot allocations remain intact.
 *
 * For UNIFORM, MIXED, and FRAGMENTED:
 * - If the selected slot is occupied, verify its payload samples, free it, mark
 *   it empty, and end this iteration without allocating a replacement.
 * - If it is empty, allocate with calloc when choice % 4 == 0, otherwise malloc.
 *   calloc receives (1, size); its payload samples must initially contain zero.
 *
 * For RESIZE:
 * - An occupied slot is freed only when choice % 4 == 0.
 * - Otherwise call realloc with the new size. Empty slots use realloc(NULL,
 *   size), which performs an initial allocation. Occupied slots may grow or
 *   shrink; samples within min(old_size, new_size) must retain their old pattern.
 *
 * Base requested sizes, in bytes (multiply every size by size_scale):
 * - UNIFORM: 64.
 * - MIXED: 4096 + size_bits % 32768 when size_bits % 8 == 0; otherwise
 *   1 + size_bits % 2048. This mixes occasional large requests with small ones.
 * - FRAGMENTED: 1024 + size_bits % 2048 (1,024..3,071).
 * - RESIZE: 1 + size_bits % 16384 (1..16,384).
 *
 * Every successful allocation/resize consumes one additional PRNG value for a
 * new byte pattern. assign() checks alignment, fills the entire requested
 * payload with that pattern, and records the new pointer and size. assign()
 * and discard() check first/middle/last payload bytes, update the checksum and
 * API call counts, and maintain current/peak live requested-byte totals.
 *
 * Each loop iteration makes exactly one allocator API call. Live allocations
 * are left in slots so the caller can record memory usage before freeing them.
 * Setup, the loop, and their helper work are timed; caller cleanup is not.
 * Allocation addresses never influence the request sequence, so successful
 * runs with the same workload, seed, step count, and size scale receive identical work.
 * Scaling also applies to FRAGMENTED setup; it consumes no additional PRNG values.
 *
 * @param workload Which of the four request patterns to run.
 * @param state Nonzero initial PRNG seed, updated locally as values are drawn.
 * @param steps Number of loop iterations, excluding FRAGMENTED setup calls.
 * @param size_scale Positive size multiplier, checked for overflow before timing.
 */
static void run_workload(enum workload workload, uint32_t state, size_t steps, size_t size_scale) {
    if (workload == FRAGMENTED) {
        for (size_t i = 0; i < SLOTS; ++i)
            assign(i, (64 + (i % 8) * 128) * size_scale, (unsigned char)i, USE_MALLOC);
        for (size_t i = 0; i < SLOTS; i += 2)
            discard(i);
    }

    for (size_t step = 0; step < steps; ++step) {
        size_t index = random_number(&state) % SLOTS;
        uint32_t choice = random_number(&state);
        uint32_t size_bits = random_number(&state);
        if (workload == FRAGMENTED)
            index &= ~(size_t)1; // Odd slots remain live to separate the holes.
        if (slots[index].ptr && (workload != RESIZE || choice % 4 == 0)) {
            discard(index);
            continue;
        }

        size_t size = workload == UNIFORM      ? 64
                      : workload == FRAGMENTED ? 1024 + size_bits % 2048
                      : workload == RESIZE     ? 1 + size_bits % 16384
                      : size_bits % 8 == 0     ? 4096 + size_bits % 32768
                                               : 1 + size_bits % 2048;
        enum allocation kind = workload == RESIZE ? USE_REALLOC
                               : choice % 4 == 0  ? USE_CALLOC
                                                  : USE_MALLOC;
        assign(index, size * size_scale, (unsigned char)random_number(&state), kind);
    }
}

static void print_string(const char *text) {
    putchar('"');
    for (const unsigned char *p = (const unsigned char *)text; *p; ++p) {
        if (*p == '"' || *p == '\\') {
            putchar('\\');
            putchar(*p);
        } else if (*p < 0x20) {
            printf("\\u%04x", (unsigned)*p);
        } else {
            putchar(*p);
        }
    }
    putchar('"');
}

static void print_stats(const struct allocator_stats *stats) {
    struct field {
        const char *name;
        size_t value;
    };
#define FIELD(name) {#name, stats->name}
    const struct field fields[] = {
        FIELD(mapped_bytes),  FIELD(peak_mapped_bytes), FIELD(arenas),
        FIELD(live_blocks),   FIELD(requested_bytes),   FIELD(capacity_bytes),
        FIELD(free_blocks),   FIELD(free_bytes),        FIELD(largest_free_block),
        FIELD(malloc_calls),  FIELD(free_calls),        FIELD(calloc_calls),
        FIELD(realloc_calls), FIELD(searches),          FIELD(search_steps),
        FIELD(splits),        FIELD(coalesces),         FIELD(mmap_calls),
        FIELD(munmap_calls)};
#undef FIELD
    putchar('{');
    for (size_t i = 0; i < sizeof(fields) / sizeof(fields[0]); ++i)
        printf("%s\"%s\":%zu", i ? "," : "", fields[i].name, fields[i].value);
    printf(",\"average_free_block_size\":%.17g}", stats->average_free_block_size);
}

static void print_checkpoint(const struct checkpoint *point, bool instrumented) {
    printf("{\"rss_kib\":%" PRIu64 ",\"peak_rss_kib\":%" PRIu64 ",\"allocator_stats\":",
           point->rss_kib, point->peak_rss_kib);
    if (instrumented)
        print_stats(&point->stats);
    else
        fputs("null", stdout);
    putchar('}');
}

int main(int argc, char **argv) {
    if (argc == 2 && (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0)) {
        usage(stdout, argv[0]);
        return EXIT_SUCCESS;
    }
    if (argc < 4) {
        usage(stderr, argv[0]);
        return EXIT_FAILURE;
    }

    // parse workload
    const char *names[] = {"uniform", "mixed", "fragmented", "resize"};
    enum workload workload = UNIFORM;
    while ((size_t)workload < sizeof(names) / sizeof(names[0]) &&
           strcmp(argv[1], names[workload]) != 0) {
        ++workload;
    }
    if ((size_t)workload == sizeof(names) / sizeof(names[0]))
        fail("unknown workload");

    uint32_t seed = (uint32_t)parse_number(argv[2], UINT32_MAX);
    size_t steps = (size_t)parse_number(argv[3], SIZE_MAX - (size_t)SLOTS * 2);

    const char *expected = NULL;
    size_t size_scale = 1;
    bool scale_provided = false;
    for (int i = 4; i < argc; ++i) {
        if (strcmp(argv[i], "--size-scale") == 0) {
            if (scale_provided || i + 1 == argc)
                fail("--size-scale requires one value and may appear only once");
            size_scale = (size_t)parse_number(argv[++i], SIZE_MAX);
            scale_provided = true;
        } else if (!expected && valid_label(argv[i])) {
            expected = argv[i];
        } else {
            fail("unknown or duplicate benchmark argument");
        }
    }

    /* Upper bounds include setup allocations. Guard both individual requests and
       the sum of up to SLOTS live payloads used by the accounting counters. */
    const size_t max_base_size[] = {64, 4096 + 32767, 3071, 16384};
    size_t maximum = max_base_size[workload];
    if (size_scale > (size_t)PTRDIFF_MAX / maximum || size_scale > SIZE_MAX / SLOTS / maximum)
        fail("size scale would overflow allocation sizes or live-byte accounting");

    struct allocator_info allocator = identify_allocator(expected);

    memset(slots, 0, sizeof(slots)); // Touch bookkeeping pages before the initial measurement.
    (void)now_ns();                  // Resolve the clock function before timing the workload.
    struct checkpoint initial = {0}, before_cleanup = {0}, after_cleanup = {0};

    capture_checkpoint(&initial, allocator.instrumented);

    uint64_t start = now_ns();
    run_workload(workload, seed, steps, size_scale);
    uint64_t elapsed = now_ns() - start;

    for (size_t i = 0; i < SLOTS; ++i) {
        if (slots[i].ptr)
            verify_samples(slots[i].ptr, slots[i].size, slots[i].pattern);
    }
    capture_checkpoint(&before_cleanup, allocator.instrumented);

    struct operations timed_calls = calls;
    size_t live_before_cleanup = live_requested;
    uint64_t workload_checksum = checksum;
    size_t total_calls =
        calls.malloc_calls + calls.calloc_calls + calls.realloc_calls + calls.free_calls;

    for (size_t i = 0; i < SLOTS; ++i) {
        if (slots[i].ptr)
            discard(i);
    }
    if (live_requested)
        fail("cleanup left live workload allocations");

    capture_checkpoint(&after_cleanup, allocator.instrumented);

    /*
     Print the result json
    {
      "schema_version": 1,
      "workload": "uniform",
      "allocator": "system",
      "variant": "glibc",
      "allocator_library": "/lib/aarch64-linux-gnu/libc.so.6",
      "seed": 1,
      "steps": 1,
      "size_scale": 1,
      "slots": 1024,
      "elapsed_ns": 5000,
      "throughput_calls_per_second": 200000,
      "operations": {
        "total": 1,
        "malloc": 1,
        "calloc": 0,
        "realloc": 0,
        "free": 0
      },
      "live_requested_bytes": 64,
      "peak_live_requested_bytes": 64,
      "checksum": 301,
      "cleanup_free_calls": 1,
      "checkpoints": {
        "initial": {
          "rss_kib": 1200,
          "peak_rss_kib": 1200,
          "allocator_stats": null
        },
        "before_cleanup": {
          "rss_kib": 1204,
          "peak_rss_kib": 1204,
          "allocator_stats": null
        },
        "after_cleanup": {
          "rss_kib": 1204,
          "peak_rss_kib": 1204,
          "allocator_stats": null
        }
      }
    }
     */
    printf("{\"schema_version\":1,\"workload\":");
    print_string(argv[1]);
    fputs(",\"allocator\":", stdout);
    print_string(allocator.strategy);
    fputs(",\"variant\":", stdout);
    print_string(allocator.variant);
    fputs(",\"allocator_library\":", stdout);
    print_string(allocator.library);
    printf(",\"seed\":%" PRIu32
           ",\"steps\":%zu,\"size_scale\":%zu,\"slots\":%d,\"elapsed_ns\":%" PRIu64,
           seed, steps, size_scale, SLOTS, elapsed);
    fputs(",\"throughput_calls_per_second\":", stdout);
    if (elapsed)
        printf("%.17g", (double)total_calls * 1e9 / (double)elapsed);
    else
        fputs("null", stdout);
    printf(",\"operations\":{\"total\":%zu,\"malloc\":%zu,\"calloc\":%zu,\"realloc\":%zu,\"free\":%"
           "zu}",
           total_calls, timed_calls.malloc_calls, timed_calls.calloc_calls,
           timed_calls.realloc_calls, timed_calls.free_calls);
    printf(",\"live_requested_bytes\":%zu,\"peak_live_requested_bytes\":%zu,"
           "\"checksum\":%" PRIu64 ",\"cleanup_free_calls\":%zu,\"checkpoints\":{\"initial\":",
           live_before_cleanup, peak_live_requested, workload_checksum,
           calls.free_calls - timed_calls.free_calls);
    print_checkpoint(&initial, allocator.instrumented);
    fputs(",\"before_cleanup\":", stdout);
    print_checkpoint(&before_cleanup, allocator.instrumented);
    fputs(",\"after_cleanup\":", stdout);
    print_checkpoint(&after_cleanup, allocator.instrumented);
    fputs("}}\n", stdout);
    if (fflush(stdout) != 0)
        fail("cannot write benchmark result");
    return EXIT_SUCCESS;
}
